reset role; select set_config('request.jwt.claims', '{"sub":"a6666666-6666-6666-6666-666666666666","role":"authenticated"}', true); set local role authenticated;
select throws_ok($$ select public.set_team_required_waiver('a1000000-0000-0000-0000-00000000000a', 'b1000000-0000-0000-0000-000000000001', false) $$, '42501', 'forbidden', 'a club admin cannot change a team''s requirements');
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.set_team_required_waiver('a1000000-0000-0000-0000-00000000000a', 'b1000000-0000-0000-0000-000000000001', false) $$, 'a manager removes the requirement');
